raw:
{
  "spells": [
    {
      "id": "spell_wind_01",
      "theory": "招风术让施法者掌心的魔力沿最短路径推挤近处空气，在两米内形成可辨识的气流。空气本身不被创造，只是被驱赶，因此烟尘会被吹偏却仍留在原处。若施术时掌心离烟源过近，未燃尽的火星可能被带起，需要先看清周围有无易燃碎屑。气流方向由手腕角度决定，施术者无法同时朝两个方向推风。",
      "casting": "五指并拢，掌心朝目标缓慢推出半臂，同时以指节在空气中划出三道短横线，待气流声起便停手。",
      "failure": "气流会在中途突然散乱，把烟尘卷回施术者面前，或让火堆边缘的灰烬溅到旁边的人身上，留下一层薄灰。",
      "counters": [
        "站在上风处并用浸湿的厚布遮住口鼻，可让气流带不走面前的烟。",
        "在烟源四周垒一圈湿石或湿土，能挡住被推起的灰烬与火星。"
      ],
      "socialConsequences": "河谷乡约中，借风驱烟是常见的邻里互助，谁家灶房倒烟，旁人搭手吹散便算人情。中陆城里的商铺也接受学徒用此术清理门前浮尘。琥珀海岸的港务人员则留意船上用风者是否把货舱里的粉尘吹向别家甲板，若因此造成货损，货主可依航运惯例追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把烟吹回自己脸上，方向感不稳。",
        "熟练后能稳定朝一个方向推出气流，驱烟不再反复。",
        "控制更细时，可在三米内选择吹散桌面浮尘而不扬尘。",
        "极高熟练度下气流几乎无声，仍只影响两米内空气。"
      ]
    },
    {
      "id": "spell_wind_02",
      "theory": "拂尘术把魔力压成一层贴附在物体表面的薄气流，沿平面滑过时带走松散尘土。魔力并不渗入材质，因此牢固污渍和油垢不会被剥离。对织物、纸张和未干的漆面施术需格外谨慎，气流可能把纤维或颜料一起掀动。施术者须先判断尘土是否混有石屑，否则滑过的气流会划伤光面。",
      "casting": "以食指与中指并拢，在物体上方三寸处由内向外画一道弧线，同时呼气一次，待表面浮尘被带走即可收指。",
      "failure": "弧线画得太急会让气流打旋，尘土被甩到旁边刚擦净的器物上；若物体是纸张，边角可能被掀起并留下折痕。",
      "counters": [
        "先用湿布把器物表面润湿，尘土粘住后气流便带不走它们。",
        "在器物周围竖起一圈硬纸或薄木板，可挡住被滑出的浮尘。"
      ],
      "socialConsequences": "西陲河谷的抄写人常请邻里用此术清理书案，乡约视之为日常互助。中陆城里的公会允许学徒在店铺内使用，但若把尘土拂到顾客衣帽上，店主须当面致歉。琥珀海岸的货栈则要求先确认货物不是待验的细料，若因吹尘导致货包标签脱落，港务会按货损记录追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时灰尘常被吹到旁边，需要反复调整手势。",
        "熟练后能沿一个方向平稳滑过，浮尘不再四散。",
        "控制更细时，可避开纸张边角，只清理桌面中央。",
        "极高熟练度下几乎不留尘痕，仍无法去除粘附污渍。"
      ]
    },
    {
      "id": "spell_wind_03",
      "theory": "传声线让施法者把声音压进一条细窄气流，沿直线送到近处听者耳中。气流只是载体，声音不会在途中被放大或改变音色。沿途若有旁人站在气流路径上，也能听到同样内容，因此它并不适合传递私密话语。气流遇到厚墙或强风会散开，声音随之模糊。",
      "casting": "双唇微合，向掌心吹出一口长气，同时用拇指在掌心画一条短直线，待气流稳定后朝听者方向轻推。",
      "failure": "气流在途中被风吹散，话语变成断续的音节，听者只能捕捉到几个字，甚至误听成完全不同的意思。",
      "counters": [
        "站在传声线路径之外，或用手掌在耳侧挡出屏障，可让声音变弱。",
        "在施术者与听者之间点起一盆炭火，上升热气会扰乱气流方向。"
      ],
      "socialConsequences": "河谷乡约中，用传声线在集市上喊人吃饭无人计较，但若用来偷听邻家谈话，乡老会要求当众说明。中陆城里的公会提醒学徒，在商铺内传话不得绕到柜台后面。琥珀海岸的港务对船与船之间传令持宽容态度，但若因听错口令导致缆绳误放或货箱碰撞，责任仍按航运事故追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时气息太短，一句话常被截成两段。",
        "熟练后能把整句平稳送出，听者不再反复追问。",
        "控制更细时，可让气流略偏，避开旁人常站的位置。",
        "极高熟练度下音色更清晰，仍会被厚墙或强风打断。"
      ]
    }
  ]
}
